// Lab 4.2, provided: the two paths a thread can take, in Metal Shading Language.
// The same functions as paths.h; see the comment there. Do not edit this file.
//
// The driver compiles kernel.metal at run time, and a library compiled from a
// source string has no search path for your own headers ("the source may only
// import the Metal default library", Apple's documentation of
// newLibraryWithSource; notes/today/ch05-facts.md, C7). So the driver pastes
// this file in place of the line
//     #include "paths.metal.h"
// before it compiles kernel.metal.
#ifndef PMPP_LAB42_PATHS_METAL_H
#define PMPP_LAB42_PATHS_METAL_H

static inline float stepA(float x) { return x * 0.999f + 0.01f; }
static inline float stepB(float x) { return x * 0.998f - 0.02f; }

static inline float pathA(float x, uint iters) {
    for (uint k = 0; k < iters; ++k) x = stepA(x);
    return x;
}

static inline float pathB(float x, uint iters) {
    for (uint k = 0; k < iters; ++k) x = stepB(x);
    return x;
}

#endif
